def majority_n3(a: list[int]) -> list[int]:
    c1 = c2 = 0
    n1 = n2 = None
    for x in a:
        if n1 == x:
            c1 += 1
        elif n2 == x:
            c2 += 1
        elif c1 == 0:
            n1, c1 = x, 1
        elif c2 == 0:
            n2, c2 = x, 1
        else:
            c1 -= 1
            c2 -= 1
    return sorted(c for c in {n1, n2} if c is not None and a.count(c) > len(a) // 3)
